import type { AgentMemory } from './agent/types';
/**
 * A Web-standard Request augmented by the EdgeOne Pages runtime.
 * Web-standard Request 被 EdgeOne Pages 运行时增强后的形态。`body` 覆写 Request.body，
 * 返回按 Content-Type 解析后的值；预加载完成前可能是一个 Promise。`cookies` / `query` 为惰性 getter。
 */
export interface EdgeoneRequest extends Omit<Request, 'body'> {
    /** Parsed cookies from the Cookie header.
     * 解析后的 Cookie（来自 Cookie header）。 */
    readonly cookies: Record<string, string>;
    /** Parsed query params: URL-decoded, arrays and boolean/number coercion supported.
     * 解析后的 query 参数：URL 解码、支持数组、布尔/数字字符串自动转换。 */
    readonly query: Record<string, unknown>;
    /** Parsed request body by Content-Type.
     * 按 Content-Type 解析后的请求体。 */
    body: unknown;
}
/**
 * SCF server info.
 * SCF 服务器信息。
 */
export interface CloudFunctionServerInfo {
    /** Deployment region.
     * 部署地域。 */
    region: string;
    /** Request ID.
     * 请求 ID。 */
    requestId: string;
}
/**
 * Route params: single-segment is string, multi-segment [[...]] is string[] (same as EdgeFunctionParams).
 * 路由参数：单段动态参数为 string，多段 [[...]] 为 string[]（与 EdgeFunctionParams 一致）。
 */
export interface CloudFunctionParams {
    [key: string]: string | string[];
}
/**
 * `context.agent` — injected only when the project has agent routes.
 * `context.agent`——仅当项目存在 agent 路由时注入。`store` 为去掉 langgraph 字段的
 * AgentMemory（对齐 cloud-function 运行时裁剪）。
 */
export interface CloudFunctionAgentContext {
    /** Conversation ID.
     * 会话 ID。 */
    conversation_id: string;
    /** Conversation memory (without langgraph fields).
     * 会话级记忆存储（无 langgraph 字段）。 */
    store: Omit<AgentMemory, 'langgraphCheckpointer' | 'langgraphStore'>;
}
/**
 * The cloud/node function handler context (parameter of `onRequest(context)`).
 * Cloud/Node 函数 handler 的上下文（`onRequest(context)` 的入参）。
 */
export interface CloudFunctionContext {
    /** Enhanced Web Request; absent on some paths (e.g. framework functions).
     * 增强 Web Request；部分路径（如 framework 函数）下不存在。 */
    request?: EdgeoneRequest;
    /** Function environment variables.
     * 函数环境变量。 */
    env: Record<string, string | undefined>;
    /** Route params.
     * 路由参数。 */
    params: CloudFunctionParams;
    /** Log UUID.
     * 日志 UUID。 */
    uuid: string;
    /** SCF server info.
     * SCF 服务器信息。 */
    server: CloudFunctionServerInfo;
    /** Client IP.
     * 客户端 IP。 */
    clientIp: string;
    /** Geo info (may be absent).
     * 地理信息（可能缺失）。 */
    geo: Record<string, string> | undefined;
    /** Agent context (present when the project has agent routes).
     * agent 上下文（项目有 agent 路由时存在）。 */
    agent?: CloudFunctionAgentContext;
}
/**
 * Cloud/Node function handler. May return a Web Response, a plain object (auto JSON 200),
 * or nothing (the runtime responds 404).
 * Cloud/Node 函数 handler。可返回 Web Response、普通对象（自动 JSON 200）、
 * 或不返回（运行时发 404）。
 */
export type CloudFunctionHandler = (context: CloudFunctionContext) => Response | Record<string, unknown> | void | Promise<Response | Record<string, unknown> | void>;
